            Console.WriteLine($"    {prop.PropertyType.Name} {prop.Name} ({accessor})");
        }
    }

    var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
        .Where(m => !m.IsSpecialName && m.DeclaringType == type).ToList();
    if (methods.Any())
    {
        Console.WriteLine($"  Methods:");
        foreach (var method in methods.OrderBy(m => m.Name))
        {
            var pars = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
            Console.WriteLine($"    {method.ReturnType.Name} {method.Name}({pars})");
        }
    }
}

