        .OrderBy(p => p.Name).ToList();
    if (props.Any())
    {
        Console.WriteLine($"{indent}  Properties:");
        foreach (var p in props)
        {
            var access = "";
            if (p.CanRead) access += "get ";
            if (p.CanWrite) access += "set ";
            Console.WriteLine($"{indent}    - {p.PropertyType.Name} {p.Name} {{{access.Trim()}}}");
        }
    }

    // Methods
    var methods = t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
        .Where(m => !m.IsSpecialName)
        .OrderBy(m => m.Name).ToList();
    if (methods.Any())
    {
        Console.WriteLine($"{indent}  Methods:");
