using System.ComponentModel;
using System.Net;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capability by scraping search results.
/// In production, replace with a dedicated search API (Bing Search, Google Custom Search, etc.).
/// </summary>
public sealed partial class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Searches the web for a given query and returns a list of result snippets. Use this to find information about a topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3,
        CancellationToken cancellationToken = default)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("User-Agent", "ResearchAgent/1.0");

            using var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();
            var html = await response.Content.ReadAsStringAsync(cancellationToken);

            var results = ParseSearchResults(html, maxResults);

            if (results.Count == 0)
                return $"No results found for '{query}'. Try rephrasing the search query.";

            return JsonSerializer.Serialize(new { query, results }, SerializerOptions);
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Try again with a different query.";
        }
    }

    private static List<SearchResult> ParseSearchResults(string html, int maxResults)
    {
        var results = new List<SearchResult>();

        // Extract snippets from DuckDuckGo Lite HTML results
        var snippetMatches = SnippetPattern().Matches(html);

        foreach (Match match in snippetMatches)
        {
            if (results.Count >= maxResults)
                break;

            var snippet = StripHtml(match.Groups[1].Value).Trim();
            if (!string.IsNullOrWhiteSpace(snippet) && snippet.Length > 20)
            {
                results.Add(new SearchResult(snippet));
            }
        }

        // Fallback: extract text from table cells containing result data
        if (results.Count == 0)
        {
            var cellMatches = TableCellPattern().Matches(html);
            foreach (Match match in cellMatches)
            {
                if (results.Count >= maxResults)
                    break;

                var text = StripHtml(match.Groups[1].Value).Trim();
                if (!string.IsNullOrWhiteSpace(text) && text.Length > 40)
                {
                    results.Add(new SearchResult(text));
                }
            }
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var text = HtmlTagPattern().Replace(html, " ");
        text = WebUtility.HtmlDecode(text);
        return WhitespacePattern().Replace(text, " ").Trim();
    }

    [GeneratedRegex(@"<td\s+class=""result-snippet""[^>]*>(.*?)</td>", RegexOptions.Singleline)]
    private static partial Regex SnippetPattern();

    [GeneratedRegex(@"<td[^>]*class=""[^""]*result[^""]*""[^>]*>(.*?)</td>", RegexOptions.Singleline)]
    private static partial Regex TableCellPattern();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex HtmlTagPattern();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespacePattern();

    private static readonly JsonSerializerOptions SerializerOptions = new() { WriteIndented = true };

    private sealed record SearchResult(string Snippet);
}

