using System.ComponentModel;
using System.Text;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capability for the research agent to organize findings.
/// </summary>
public sealed class NoteTool
{
    private readonly List<Note> _notes = [];
    private readonly object _lock = new();

    [Description("Saves a research note with a title and content. Use this to record key findings from web searches.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The note content — a fact, insight, or key finding")] string content)
    {
        lock (_lock)
        {
            var note = new Note(Id: _notes.Count + 1, Title: title, Content: content);
            _notes.Add(note);
            return $"Note #{note.Id} saved: \"{title}\"";
        }
    }

    [Description("Lists all saved research notes. Use this to review what you've gathered so far before writing a summary.")]
    public string ListNotes()
    {
        lock (_lock)
        {
            if (_notes.Count == 0)
                return "No notes saved yet.";

            var sb = new StringBuilder();
            sb.AppendLine($"=== {_notes.Count} Research Notes ===");
            foreach (var note in _notes)
            {
                sb.AppendLine($"[#{note.Id}] {note.Title}");
                sb.AppendLine($"  {note.Content}");
                sb.AppendLine();
            }
            return sb.ToString();
        }
    }

    [Description("Deletes a note by its ID number.")]
    public string DeleteNote(
        [Description("The ID number of the note to delete")] int noteId)
    {
        lock (_lock)
        {
            var note = _notes.FirstOrDefault(n => n.Id == noteId);
            if (note is null)
                return $"Note #{noteId} not found.";

            _notes.Remove(note);
            return $"Note #{noteId} (\"{note.Title}\") deleted.";
        }
    }

    public IReadOnlyList<Note> GetAllNotes()
    {
        lock (_lock)
        {
            return [.. _notes];
        }
    }

    public sealed record Note(int Id, string Title, string Content);
}

