+
+var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
+    ?? throw new InvalidOperationException(
+        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");
+
+var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";
+
+// Build tools
+var httpClient = new HttpClient();
+var webSearch = new WebSearchTool(httpClient);
+var notes = new NoteTool();
+
+var tools = new List<AITool>
+{
+    AIFunctionFactory.Create(webSearch.SearchWebAsync, name: "search_web"),
+    AIFunctionFactory.Create(notes.SaveNote, name: "save_note"),
+    AIFunctionFactory.Create(notes.ListNotes, name: "list_notes"),
+    AIFunctionFactory.Create(notes.DeleteNote, name: "delete_note"),
+};
+
+// Build the chat client through the MEAI abstraction
+var openAIClient = new OpenAIClient(new ApiKeyCredential(apiKey));
+IChatClient chatClient = openAIClient
+    .GetChatClient(modelId)
+    .AsIChatClient();
+
+// Configure the agent
+var agentOptions = new ChatClientAgentOptions
+{
+    Name = "ResearchAgent",
+    Description = "An AI research assistant that searches the web and takes notes to produce summaries.",
+    ChatOptions = new ChatOptions
+    {
+        Temperature = 0f,
+        MaxOutputTokens = 4096,
+        Tools = tools,
+        ToolMode = ChatToolMode.Auto,
+    },
+};
+
+var agent = new ChatClientAgent(chatClient, agentOptions);
+
+// Interactive loop
+Console.WriteLine("╔══════════════════════════════════════════╗");
+Console.WriteLine("║       🔍 AI Research Agent               ║");
+Console.WriteLine("║  Enter a topic to research, or 'quit'.   ║");
+Console.WriteLine("╚══════════════════════════════════════════╝");
+Console.WriteLine();
+
+while (true)
+{
+    Console.ForegroundColor = ConsoleColor.Cyan;
+    Console.Write("Research topic> ");
+    Console.ResetColor();
+
+    var topic = Console.ReadLine()?.Trim();
+    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
+    {
+        Console.WriteLine("Goodbye!");
+        break;
+    }
+
+    var prompt = $"""
+        Research the following topic thoroughly:
+
+        **{topic}**
+
+        Follow these steps:
+        1. Search the web for information about this topic (use 2-3 different search queries to cover different angles).
+        2. Save the most important findings as notes using the save_note tool.
+        3. Review your notes with list_notes.
+        4. Write a comprehensive summary that synthesizes all your research notes into a well-structured report.
+
+        Be thorough but concise. Cite specific facts from your searches.
+        """;
+
+    var messages = new List<ChatMessage>
+    {
+        new(ChatRole.User, prompt),
+    };
+
+    Console.WriteLine();
+    Console.ForegroundColor = ConsoleColor.DarkGray;
+    Console.WriteLine($"Researching \"{topic}\"...");
+    Console.ResetColor();
+
+    try
+    {
+        var response = await agent.RunAsync(messages, session: null);
+
+        Console.WriteLine();
+        Console.ForegroundColor = ConsoleColor.Green;
+        Console.WriteLine("═══ Research Summary ═══");
+        Console.ResetColor();
+
+        // Display the final response
+        foreach (var msg in response.Messages)
+        {
+            if (msg.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(msg.Text))
+            {
+                Console.WriteLine(msg.Text);
+            }
+        }
+
+        // Show collected notes
+        var allNotes = notes.GetAllNotes();
+        if (allNotes.Count > 0)
+        {
+            Console.WriteLine();
+            Console.ForegroundColor = ConsoleColor.Yellow;
+            Console.WriteLine($"═══ {allNotes.Count} Notes Collected ═══");
+            Console.ResetColor();
+            foreach (var note in allNotes)
+            {
+                Console.WriteLine($"  [{note.Id}] {note.Title}: {note.Content[..Math.Min(note.Content.Length, 100)]}...");
+            }
+        }
+    }
+    catch (Exception ex)
+    {
+        Console.ForegroundColor = ConsoleColor.Red;
+        Console.WriteLine($"Error: {ex.Message}");
+        Console.ResetColor();
+    }
+
+    Console.WriteLine();
+}
+
+httpClient.Dispose();

